// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }

    function testFuzz_property(address caller, uint256 newLimit) public {
        vm.assume(caller != address(0));

        uint256 before = c.currentBetLimit();

        vm.deal(caller, 1 ether);

        bool ok;
        vm.prank(caller);
        try c.AdjustBetAmounts(newLimit) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 afterCall = c.currentBetLimit();

        if (caller != address(this)) {
            assertTrue(afterCall == before);
        } else {
            assertTrue(afterCall == newLimit);
        }
    }
}
